fun HazardScreenSettingsSection(
    accent: Color,
    expanded: Boolean,
    onExpandedChange: (Boolean) -> Unit,
    summary: String,
    onReset: (() -> Unit)? = null,
    content: @Composable () -> Unit,
) {
    Surface(
        Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 6.dp),
        color = SurfaceDark,
        shape = RoundedCornerShape(18.dp),
    ) {
        Column(
            Modifier
                .background(
                    Brush.horizontalGradient(
                        listOf(accent.copy(alpha = 0.14f), Color.Transparent),
                    ),
                ),
        ) {
            Row(
                Modifier
                    .fillMaxWidth()
                    .clickable { onExpandedChange(!expanded) }
                    .padding(16.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Icon(
                    Icons.Filled.Settings,
                    contentDescription = null,
                    tint = accent,
                    modifier = Modifier.size(22.dp),
                )
                Spacer(Modifier.width(10.dp))
                Column(Modifier.weight(1f)) {
                    Text(
                        "Settings",
                        color = Color.White,
                        fontWeight = FontWeight.SemiBold,
                        fontSize = 15.sp,
                    )
                    Text(
                        if (expanded) {
                            "Ad-hoc only — does not change app Settings defaults"
                        } else {
                            summary
                        },
                        color = OnSurfaceMuted,
                        fontSize = 11.sp,
                        maxLines = 2,
                    )
                }
                Icon(
                    if (expanded) Icons.Filled.ExpandLess else Icons.Filled.ExpandMore,
                    contentDescription = if (expanded) "Collapse settings" else "Expand settings",
                    tint = OnSurfaceMuted,
                )
            }
            AnimatedVisibility(visible = expanded) {
                Column(Modifier.padding(start = 8.dp, end = 8.dp, bottom = 8.dp)) {
                    content()
                    if (onReset != null) {
                        Surface(
                            Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 8.dp, vertical = 4.dp)
                                .clickable(onClick = onReset),
                            color = Color(0xFF2A363C),
                            shape = RoundedCornerShape(14.dp),
                        ) {
                            Row(
                                Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = 14.dp, vertical = 12.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.Center,
                            ) {
                                Icon(
                                    Icons.Filled.RestartAlt,
                                    contentDescription = null,
                                    tint = accent,
                                    modifier = Modifier.size(20.dp),
                                )
                                Spacer(Modifier.width(8.dp))
                                Text(
                                    "Reset to defaults",
                                    color = Color.White,
                                    fontWeight = FontWeight.SemiBold,
                                    fontSize = 14.sp,
                                )
                            }
                        }
                    }
                    // Footer: collapse without scrolling back to the header
                    Surface(
                        Modifier
                            .fillMaxWidth()
