@SuppressLint("LocalContextGetResourceValueCall")
@Composable
fun FavoriteDialog(
    type: IFavorites.FavoriteType,
    id: String,
    metadata: FavoriteManager.FavoriteMetadata,
    groupMetadata: Map<String, FavoriteManager.FavoriteGroupMetadata>,
    maximumFavorites: Int,
    onDismiss: () -> Unit,
    onConfirmation: () -> Unit
) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()

    val selectedGroup = remember { mutableStateOf("") }
    val groups = remember { mutableStateListOf<String>() }

    LaunchedEffect(Unit) {
        when (type) {
            IFavorites.FavoriteType.FAVORITE_VRC_PLUS_WORLD,    // never actually used here.
            IFavorites.FavoriteType.FAVORITE_WORLD -> {
                FavoriteManager.worldListState.value.forEach {
                    groups.add(it.key)
                }

                if (groups.isEmpty()) {
                    onDismiss()
                } else {
                    selectedGroup.value = groups[0]
                }
            }
            IFavorites.FavoriteType.FAVORITE_AVATAR -> {
                FavoriteManager.avatarListState.value.forEach {
                    groups.add(it.key)
                }

                if (groups.isEmpty()) {
                    onDismiss()
                } else {
                    selectedGroup.value = groups[0]
                }
            }

            IFavorites.FavoriteType.FAVORITE_FRIEND -> {
                FavoriteManager.friendListState.value.forEach {
                    groups.add(it.key)
                }

                if (groups.isEmpty()) {
                    onDismiss()
                } else {
                    selectedGroup.value = groups[0]
                }
            }

            IFavorites.FavoriteType.FAVORITE_NONE -> {   }
        }
    }

    AlertDialog(
        title = {
            Text(text = stringResource(R.string.favorite_dialog_title))
        },
        text = {
            LazyColumn(
                verticalArrangement = Arrangement.SpaceEvenly,
                horizontalAlignment = Alignment.Start,
                modifier = Modifier.padding(8.dp)
            ) {
                item {
                    groups.forEach {
                        val displayName = groupMetadata[it]?.displayName ?: groupMetadata[it]?.name ?: it
                        val currentSize = groupMetadata[it]?.size ?: 0

                        Row(
                            Modifier
                                .fillMaxWidth()
                                .selectable(
                                    selected = (it == selectedGroup.value),
                                    onClick = { selectedGroup.value = it }),
                            horizontalArrangement = Arrangement.Start,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            RadioButton(selected = it == selectedGroup.value, onClick = {
                                selectedGroup.value = it
                            })
                            Text(text = "$displayName ($currentSize/$maximumFavorites)")
                        }
                    }
                }
            }
        },
        onDismissRequest = {
            onDismiss()
        },
        confirmButton = {
            TextButton(
                onClick = {
                    coroutineScope.launch {
                        val result = if (selectedGroup.value.contains("vrcPlusWorld")) {
                            FavoriteManager.addFavorite(IFavorites.FavoriteType.FAVORITE_VRC_PLUS_WORLD, id, selectedGroup.value, metadata)
                        } else {
                            FavoriteManager.addFavorite(type, id, selectedGroup.value, metadata)
                        }

                        if (result) {
                            Toast.makeText(
                                context,
                                context.getString(R.string.favorite_toast_favorite_added).format(metadata.name),
                                Toast.LENGTH_SHORT
                            ).show()
                        } else {
                            Toast.makeText(
                                context,
                                context.getString(R.string.favorite_toast_favorite_added_failed).format(metadata.name),
                                Toast.LENGTH_SHORT
                            ).show()
                        }

                        onConfirmation()
                    }
                }
            ) {
                Text(stringResource(R.string.favorite_dialog_button_add))
            }
        },
        dismissButton = {
            TextButton(
                onClick = { onDismiss() }
            ) {
                Text(stringResource(R.string.favorite_dialog_button_cancel))
            }
        }
    )
}

