private fun BinRow(
    item: InboxItem,
    richAvatars: Boolean,
    onRestore: () -> Unit,
    onDeleteForever: () -> Unit,
    onPreview: () -> Unit,
) {
    val message = item.message
    ListItem(
        // Rows in the bin are truncated to two lines, which is rarely enough
        // to decide between restoring and deleting forever - tapping opens the
        // whole message.
        modifier = Modifier.clickable(onClick = onPreview),
        leadingContent = {
            SenderAvatar(
                name = item.display.name,
                richAvatars = richAvatars,
                photoUri = item.display.photoUri,
                isKnownSender = item.display.isKnownSender,
                glyph = item.glyph,
            )
        },
        headlineContent = {
            Text(
                text = item.display.name,
                style = MaterialTheme.typography.titleMedium,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        },
        supportingContent = {
            Column {
                Text(
                    text = message.body,
                    style = MaterialTheme.typography.bodyMedium,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
                Spacer(Modifier.height(4.dp))
                CategoryBadge(category = message.category)
            }
        },
        trailingContent = {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Column(horizontalAlignment = Alignment.End) {
                    Text(
                        text = item.timeLabel,
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
                IconButton(onClick = onRestore) {
                    Icon(
                        Icons.Outlined.RestoreFromTrash,
                        contentDescription = stringResource(R.string.bin_restore),
                    )
                }
                IconButton(onClick = onDeleteForever) {
                    Icon(
                        Icons.Outlined.DeleteForever,
                        contentDescription = stringResource(R.string.bin_delete_forever),
                    )
                }
            }
        },
    )
}

